import{c as t,Q as o,j as d,m as r}from"./chunks/framework.BXc4yaFE.js";const h=JSON.parse('{"title":".claude Roster + Body 稽核（v5 打掉重來的前置量測）","description":"","frontmatter":{},"headers":[],"relativePath":"research/reports/2026-07-26-roster-and-body-audit-for-v5.md","filePath":"research/reports/2026-07-26-roster-and-body-audit-for-v5.md","lastUpdated":1785909234000}'),a={name:"research/reports/2026-07-26-roster-and-body-audit-for-v5.md"};function s(n,e,c,i,p,g){return o(),d("div",null,[...e[0]||(e[0]=[r(`<h1 id="claude-roster-body-稽核-v5-打掉重來的前置量測" tabindex="-1">.claude Roster + Body 稽核（v5 打掉重來的前置量測） <a class="header-anchor" href="#claude-roster-body-稽核-v5-打掉重來的前置量測" aria-label="Permalink to &quot;.claude Roster + Body 稽核（v5 打掉重來的前置量測）&quot;">​</a></h1><blockquote><p>2026-07-26 · 執行：<code>.claude/workflows/skill-roster-audit.js</code>（7× quality lens worker + 1× ceiling 合成）+ parent 親跑確定性 gate 目的：使用者要求「優化和刪除與精鍊 .claude 的所有檔案」，本報告先量測<strong>有多少可刪</strong>，避免在乾淨的機構上做破壞性重寫。</p></blockquote><h2 id="_0-結論-先講" tabindex="-1">0. 結論（先講） <a class="header-anchor" href="#_0-結論-先講" aria-label="Permalink to &quot;0. 結論（先講）&quot;">​</a></h2><p><strong><code>.claude</code> 的機構層是乾淨的；「刪檔省 token」這條路已被量測封死。</strong></p><table tabindex="0"><thead><tr><th>路徑</th><th>量測</th><th>判定</th></tr></thead><tbody><tr><td>壓 skill/agent <code>description</code></td><td>45 項 19,976 bytes，前 12 大僅佔 39%、中位數 411 bytes、無離群值</td><td>❌ 死路（分佈平坦，要動全部 45 項才有量級效果，而那正是傷路由）</td></tr><tr><td>刪/併 skill/agent 減少項目數</td><td>12 個 overlap cluster → 5 candidate → <strong>僅 1 項真能減項</strong>，淨省 406 bytes（2.0%）</td><td>❌ 近乎死路</td></tr><tr><td>刪 hooks</td><td>26 檔、<strong>25 已接線、0 孤兒</strong>、11 hard-block / 14 advisory</td><td>❌ 無死碼可刪</td></tr></tbody></table><p>使用者感知的「harness 沒跟上 Loop Engineering 與 Graph Engineering」<strong>是教義過時，不是檔案臃腫</strong>。v5 的價值在重寫條文，不在砍檔。</p><h2 id="_1-roster-稽核結果-5-candidate-全數過-parent-gate" tabindex="-1">1. Roster 稽核結果（5 candidate，全數過 parent gate） <a class="header-anchor" href="#_1-roster-稽核結果-5-candidate-全數過-parent-gate" aria-label="Permalink to &quot;1. Roster 稽核結果（5 candidate，全數過 parent gate）&quot;">​</a></h2><table tabindex="0"><thead><tr><th>#</th><th>對象</th><th>動作</th><th>淨 bytes</th><th>要點</th></tr></thead><tbody><tr><td>1</td><td><code>harness-core</code> → <code>harness-meta</code></td><td>merge</td><td><strong>−406</strong></td><td>唯一真減項（45→44）。兩者 description 都直寫「四層／L1-L4」，router 每 session 消歧。<strong>執行前提</strong>：<code>:export</code>/<code>:apply</code> 觸發詞須逐字保留（166 bytes 已計入），否則「換模型／接入非 Claude 環境」的低頻高代價入口發現率下降</td></tr><tr><td>2</td><td><code>deep-understanding</code></td><td>sharpen</td><td>−92</td><td>與 <code>know-your-unknowns</code> 在 <code>teach me</code>/<code>教我懂</code> 字面碰撞；後者是 L1 canonical 不可動，故修前者。<strong>嚴禁升級為 merge</strong>（教人 vs 挖未知是不同主體）</td></tr><tr><td>3</td><td><code>harness-meta</code></td><td>sharpen</td><td>0</td><td><code>Dream Pass</code> 與 <code>dreaming-consolidator</code> 觸發詞對撞，且誤路由會實跑 <code>scripts/dream.py</code>（約 $4/run）。花 bytes 買防錯</td></tr><tr><td>4</td><td><code>ship</code></td><td>sharpen</td><td>0</td><td>排除子句漏了「已有 PR、只要 gate-then-merge」→ <code>verified-merge</code>。兩者皆不可停用（後者是 merge 前 4 道不可逆閘門）</td></tr><tr><td>5</td><td><code>memory-compactor</code> command/agent</td><td>sharpen</td><td>0</td><td><strong>偽陽性攔截</strong>：lens 判為 <code>duplicate</code> 建議 merge，合成者反駁成功</td></tr></tbody></table><h3 id="_1-1-合成者主動擋下的偽陽性-本次最有價值的單一輸出" tabindex="-1">1.1 合成者主動擋下的偽陽性（本次最有價值的單一輸出） <a class="header-anchor" href="#_1-1-合成者主動擋下的偽陽性-本次最有價值的單一輸出" aria-label="Permalink to &quot;1.1 合成者主動擋下的偽陽性（本次最有價值的單一輸出）&quot;">​</a></h3><p>lens worker 把 <code>memory-compactor</code> 的 command 與 agent 判為重複並建議合併。ceiling 合成者查證後反駁，parent 以 grep 重驗確認：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>.claude/commands/memory-compactor.md:11   wc -l memory/MEMORY.md</span></span>
<span class="line"><span>.claude/commands/memory-compactor.md:13   若 ≤ 200 行 → 回報「未達壓縮門檻」並結束。</span></span>
<span class="line"><span>.claude/commands/memory-compactor.md:15   超過 200 行 → 委派 memory-compactor sub-agent 執行壓縮</span></span></code></pre></div><p>command 在主 context 親跑門檻預檢後才委派——這正是「確定性 gate main 親跑，不跨 agent 邊界」要求的形狀。<strong>合併等於把 gate 推進 sub-agent，以省 110 bytes 換掉一道閘門</strong>，是清單中報酬最差、風險最高的交易。</p><h2 id="_2-body-層盤點-parent-親跑-確定性" tabindex="-1">2. Body 層盤點（parent 親跑，確定性） <a class="header-anchor" href="#_2-body-層盤點-parent-親跑-確定性" aria-label="Permalink to &quot;2. Body 層盤點（parent 親跑，確定性）&quot;">​</a></h2><p>26 檔 221,763 bytes，<code>settings.json</code> 接線 25 個，<strong>孤兒 0、接線但檔案不存在 0</strong>。</p><p><strong>hard-block（11）</strong>：<code>block-dangerous.sh</code>（41KB，最大）· <code>branch-isolation-guard.sh</code> · <code>merge-gate-mcp.sh</code> · <code>post-edit.sh</code> · <code>pre-commit-review.sh</code> · <code>pre-compact.sh</code> · <code>protect-sensitive-files.sh</code> · <code>session-init.sh</code> · <code>test-integrity-guard.sh</code> · <code>usage-delegation-gate.sh</code> · <code>user-prompt-submit.sh</code></p><p><strong>advisory（14）</strong>：<code>audit-permission</code> · <code>blindspot-domain-lint</code> · <code>gate-widening-guard</code> · <code>literal-specialcase-lint</code> · <code>memory-pr-record</code> · <code>memory-sync</code> · <code>post-compact</code> · <code>pre-push-cost</code> · <code>session-end</code> · <code>session-stop</code> · <code>taste-reference-lint</code> · <code>test-file-redflag</code> · <code>tool-log</code> · <code>unicode-covert-channel-guard</code></p><blockquote><p>advisory 群的已知結構性弱點（SPEC-v4 §6 #2c 實測）：exit 1 的 stderr <strong>不進 acting agent context</strong>，hook 開火但模型看不見——這是 F7/F15 紅軸四輪不動的歸因。v5 若要動 Body，<strong>這裡才是槓桿</strong>（把有價值的 advisory 升為 exit 2），而不是刪檔。</p></blockquote><h2 id="_3-graph-engineering-自我教訓-本次-run-自身的-roi" tabindex="-1">3. Graph Engineering 自我教訓（本次 run 自身的 ROI） <a class="header-anchor" href="#_3-graph-engineering-自我教訓-本次-run-自身的-roi" aria-label="Permalink to &quot;3. Graph Engineering 自我教訓（本次 run 自身的 ROI）&quot;">​</a></h2><p>本次 workflow 花 <strong>549,448 subagent tokens</strong> 找到 <strong>406 bytes/session</strong> 的節省。以任何算法都是負 ROI。</p><p><code>[對已最佳化的資產跑 audit sweep]</code> → <code>[先用確定性量測估上界，再決定要不要 fan-out]</code></p><p><strong>這條要進 v5 的 Graph Engineering 章節</strong>：fan-out 前先問「這件事的<strong>節省上界</strong>是多少？」——上界可用確定性命令估出來時（如本例：description 總量 20KB、分佈已知平坦），就不該用 8 個 agent 去確認一個 bash 能算出來的結論。廣度發現只在「不知道有多少東西可找」時才划算。</p><hr><blockquote><p>收據：candidate 路徑存在性 6/6 通過；evidence 逐字 grep 5/5 命中 digest；memory-compactor 反駁主張經 grep 獨立確認。</p></blockquote>`,23)])])}const m=t(a,[["render",s]]);export{h as __pageData,m as default};
